"""Create the human-readable attribution index from the actual slicing config."""
from pathlib import Path
import json,collections
HERE=Path(__file__).resolve().parents[1];c=json.loads((HERE/'slicing.json').read_text());sources=json.loads((HERE/'sources.json').read_text());byfile={s['file']:s for s in sources};used=set()
def collect(r):
 used.add(r['source'])
 for p in r.get('compose',{}).get('parts',[]):collect(p['frame'])
for a in c['assets'].values():
 for r in a['frames']+a.get('animationSources',[]):collect(r)
for t in c['themes'].values():
 for l in t['layers']:collect(l)
lines=['# Mario asset sources','', 'Nintendo property, used for a private educational class demo only; do not distribute publicly; Kenney CC0 pack remains the public-safe fallback.','', 'Only raster game imagery and frame metadata are curated. No Nintendo code, ROMs, encryption keys, executable game code, or Scratch gameplay scripts are included in the pack. The OpenWE mirror has an AGPL software licence; none of its executable code is reused. That software licence does not turn Nintendo artwork into freely licensed assets. Source rights and renderer provenance are recorded separately below.','', '## Download methods actually tested','', '- The Spriters Resource: direct HTTP requests returned 403. Real Playwright Chromium (installed Chromium 1243) also reached Cloudflare verification with HTTP 403; browser cookies did not provide a usable image response.', '- Wayback URLs tested for the old sheet path returned 404, including the requested `2025id_` form.', '- Successful method: public GitHub image/frame mirrors, content-addressed Scratch image downloads from credited collections, and the Super Mario Wiki native Grinder capture. The itch.io browser download worked, but its sheet identifies **NSMB Wii Small Mario, D. Dazzle** and is **not used** in this pack. The Scratch fan-vector Goomba and traced Mario sheet were also rejected.', '', '## Original sheets and credited collections','', '| Source | Game/style | Credit as shown by source | Used for |','|---|---|---|---|', '| [Tileset (NSMBU), asset 119099](https://www.spriters-resource.com/nintendo_switch/supermariomaker2/asset/119099/) | Super Mario Maker 2 / NSMBU | **Random Talking Bush** | Related original terrain rip. Direct ZIP blocked; corresponding 64px sheets obtained from the mirror URLs below. |', '| [Pack 1](https://scratch.mit.edu/projects/105733943/) | Super Mario Maker / NSMBU | **RandomTalkingBush**; **Woody601 for the Goomba** (that vector Goomba is not used) | Native Bullet Bill and door frames. |', '| [Pack 2](https://scratch.mit.edu/projects/105789235/) | Super Mario Maker / NSMBU | **RandomTalkingBush from TSR** | Question Block, Note Block, conveyor and Super Star. |', '| [Pack 3](https://scratch.mit.edu/projects/107756944/) | Super Mario Maker / NSMBU | **RandomTalkingBush** | Koopa, shell, Chain Chomp/chain and Spiny. Shared by **MarioTheBest**. |', '| [Grinder file](https://www.mariowiki.com/File:SMM-NSMBU-Grinder.png) | Super Mario Maker / NSMBU | **MatiasNTRM**, current file history: 10 April 2023, captured from Cemu | 149×149 rendered Grinder. |', '| [OpenWE image mirror](https://github.com/Sicraftails/SMM-WE-OpenWE/tree/2f84414054c576bf7ca03dfa33b244ee730d57da/sprites) | Folders labelled NSMBU; Maker/NSMBU style captures and background adaptations | Mirror maintainer **Sicraftails**, project based on **Andoyt**’s World Engine. **Original ripper/character renderer not stated in this mirror**; do not attribute these unverified frames to RTB. | Big/small Mario poses, native Luigi walk, remaining lower-resolution objects, and aligned background layers. |', '', '**Unconfirmed provenance:** the first mirror labels these NSMBU, and they visually use rendered art, but the exact original game version, native render scale, and original ripper of each of its player/background captures are not supplied. These are not claimed to be untouched HD SMM2 player sprites. Luigi big is a locally derived Mario colour variant. See README.md for all substitutions.','', 'The full-resolution terrain mirror is pinned to a Git revision; the sprite mirror is pinned to `2f84414054c576bf7ca03dfa33b244ee730d57da`. Scratch image names are content hashes. `sources.json` records every exact download URL and SHA-256, including unused initial candidate frames, so raw downloads can be verified. `slicing.json` records every exact pixel rectangle and source composition.','', '## Every source PNG used by the slicer','', '| Raw download | Exact image URL | Credit / provenance |','|---|---|---|']
for f in sorted(used):
 s=byfile[f]
 credit=s.get('credit') or ('Random Talking Bush, terrain mirror; original sheet reference above' if f.startswith('tiles/') else 'MatiasNTRM, Super Mario Wiki' if f=='grinder.png' else 'Nintendo imagery; original ripper/renderer not stated in mirror')
 lines.append(f'| `{f}` | [PNG]({s["url"]}) | {credit} |')
lines += ['', '## Ancillary public-safe assets','', 'The unchanged existing `/assets/` UI/editor images and sound/music files remain CC0 and are referenced by absolute URLs. See `assets/CREDITS.md` and `web/public/assets/credits.json` for their existing source credits. No existing Kenney file is modified.', '', '## Local transformations','', '- Exact crops and transparent-border trimming; fixed native frame canvases with bottom-centred feet.', '- Native flagpole/flag/base composition, and Koopa + wings composition.', '- Hue-selected Mario clothing recolour for the disclosed Luigi big substitute; no anatomical model claim.', '- Native background mirror-repeat periods to make every wide output seam match.', '- No AI image generation or Nintendo source-code reuse. No SMB1, SMB3 or SMW art fallback.', '']
(HERE/'SOURCES.md').write_text('\n'.join(lines))
print(f'SOURCES.md indexes {len(used)} used source PNGs, their exact URLs and source credits.')
